create extension if not exists pgcrypto;
create type public.global_pay_transaction_status as enum ('pending','processing','completed','failed','reversed','refunded');
create type public.global_pay_transaction_type as enum ('payment','transfer','deposit','withdrawal','exchange','refund');
create table if not exists public.global_pay_wallets (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,currency text not null check (currency in ('USD','EUR','GBP','NGN')),balance_minor bigint not null default 0 check (balance_minor >= 0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,currency));
create table if not exists public.global_pay_transactions (id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,type public.global_pay_transaction_type not null,status public.global_pay_transaction_status not null default 'pending',currency text not null,amount_minor bigint not null check (amount_minor > 0),fee_minor bigint not null default 0 check (fee_minor >= 0),reference text not null unique,provider text,provider_reference text,idempotency_key text unique,metadata jsonb not null default '{}'::jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.global_pay_ledger_entries (id uuid primary key default gen_random_uuid(),transaction_id uuid not null references public.global_pay_transactions(id) on delete restrict,wallet_id uuid not null references public.global_pay_wallets(id) on delete restrict,direction text not null check (direction in ('debit','credit')),amount_minor bigint not null check (amount_minor > 0),created_at timestamptz not null default now());
alter table public.global_pay_wallets enable row level security; alter table public.global_pay_transactions enable row level security; alter table public.global_pay_ledger_entries enable row level security;
create policy "wallet owner select" on public.global_pay_wallets for select to authenticated using ((select auth.uid())=user_id);
create policy "transaction owner select" on public.global_pay_transactions for select to authenticated using ((select auth.uid())=user_id);
create policy "ledger through owned transaction" on public.global_pay_ledger_entries for select to authenticated using (exists(select 1 from public.global_pay_transactions t where t.id=transaction_id and t.user_id=(select auth.uid())));
